    expect(qualifiedModels([FAST, SLOW], qualifications, 'mecanica', 1).map((q) => q.entry.name)).toEqual([SLOW.name, FAST.name])
  })
})

describe('forma de cada tipo de cualificación', () => {
  test('una de tarea exige su clase', () => {
